//refAssemblies: TCAdmin.SDK.dll, TCAdmin.Docker.SDK.dll, TCAdmin.Scripting.dll, TCAdmin.Monitor.dll, TCAdmin.Web.Shared.dll
using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;
using Microsoft.EntityFrameworkCore;
using TCAdmin.Web.Shared.Models;
using TCAdmin.Web.Shared.Models.Enums;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpDockerGlobals();

var service = await DockerServiceManager.GetAsync(ThisService.ServiceId);
if (service == null) { ScriptConsole.WriteLine("{0}", "FAILED: Service not found."); return; }

var clusterName = ReadText(service.Variables, "clusterName", "galera_cluster");
var lines = new List<string>();

// ---- what the running node says about itself ------------------------------
if (ThisService.Status != EServiceStatus.Started)
{
    lines.Add("This node is not running (TCAdmin status: " + ThisService.Status + "), so it cannot be queried.");
    lines.Add("Start it, then run this action again.");
    lines.Add(string.Empty);
}
else
{
    var password = ReadText(service.Variables, "RootPassword", string.Empty);
    if (password.Length == 0)
    {
        lines.Add("FAILED: no root password is stored for this node.");
    }
    else
    {
        var root = service.RootDirectory;
        var cnfPath = Path.Combine(root, ".tcadmin-galera.cnf");
        var shPath = Path.Combine(root, ".tcadmin-galera-status.sh");
        File.WriteAllText(cnfPath, "[client]\nuser=root\npassword=" + password + "\n");
        File.WriteAllText(shPath,
            "#!/bin/sh\numask 077\np=/tmp/.tcadmin-galera.cnf\ntrap 'rm -f \"$p\"' EXIT\n" +
            "cp /mnt/server/.tcadmin-galera.cnf \"$p\"\n" +
            "exec mariadb --defaults-extra-file=\"$p\" -N -B -e \"SHOW GLOBAL STATUS LIKE 'wsrep_%'; SHOW GLOBAL VARIABLES LIKE 'wsrep_cluster_name'; SHOW GLOBAL VARIABLES LIKE 'wsrep_node_name'; SHOW GLOBAL VARIABLES LIKE 'wsrep_cluster_address';\"\n");

        var raw = string.Empty;
        try
        {
            var bytes = await DockerServiceManager.ExecConsoleSingleCommand(service, "/bin/sh /mnt/server/.tcadmin-galera-status.sh", ThisCancellationToken);
            raw = Encoding.UTF8.GetString(bytes);
        }
        finally
        {
            try { File.Delete(cnfPath); File.Delete(shPath); } catch { }
        }

        var status = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        foreach (var line in raw.Replace("\r\n", "\n").Replace('\r', '\n').Split('\n'))
        {
            var tab = line.IndexOf('\t');
            if (tab <= 0) continue;
            status[line.Substring(0, tab).Trim()] = line.Substring(tab + 1).Trim();
        }

        if (status.Count == 0)
        {
            lines.Add("FAILED: could not read wsrep status from MariaDB. Raw output follows:");
            foreach (var line in raw.Replace("\r\n", "\n").Replace('\r', '\n').Split('\n')) lines.Add("  " + line);
        }
        else
        {
            var state = Pick(status, "wsrep_local_state_comment");
            var clusterStatus = Pick(status, "wsrep_cluster_status");
            var size = Pick(status, "wsrep_cluster_size");
            var ready = Pick(status, "wsrep_ready");
            var connected = Pick(status, "wsrep_connected");

            lines.Add("Galera cluster status");
            lines.Add("  node            : " + Pick(status, "wsrep_node_name"));
            lines.Add("  cluster         : " + Pick(status, "wsrep_cluster_name"));
            lines.Add("  node state      : " + state);
            lines.Add("  cluster status  : " + clusterStatus);
            lines.Add("  cluster size    : " + size);
            lines.Add("  connected/ready : " + connected + " / " + ready);
            lines.Add("  cluster uuid    : " + Pick(status, "wsrep_cluster_state_uuid"));
            lines.Add("  members online  : " + Pick(status, "wsrep_incoming_addresses"));
            lines.Add("  seeded from     : " + Pick(status, "wsrep_cluster_address"));
            lines.Add("  last committed  : " + Pick(status, "wsrep_last_committed"));
            lines.Add("  recv queue avg  : " + Pick(status, "wsrep_local_recv_queue_avg"));
            lines.Add("  flow ctl paused : " + Pick(status, "wsrep_flow_control_paused"));
            lines.Add("  cert failures   : " + Pick(status, "wsrep_local_cert_failures"));
            lines.Add("  provider        : " + Pick(status, "wsrep_provider_version"));
            lines.Add(string.Empty);

            var synced = string.Equals(state, "Synced", StringComparison.OrdinalIgnoreCase);
            var primary = string.Equals(clusterStatus, "Primary", StringComparison.OrdinalIgnoreCase);
            var live = string.Equals(ready, "ON", StringComparison.OrdinalIgnoreCase) && string.Equals(connected, "ON", StringComparison.OrdinalIgnoreCase);

            if (synced && primary && live)
                lines.Add("VERDICT: HEALTHY - this node is in sync with a primary cluster of " + size + ".");
            else if (primary && !synced)
                lines.Add("VERDICT: IN PROGRESS - the node is '" + state + "'. State transfer or catch-up is still running; check again in a minute.");
            else if (!primary)
                lines.Add("VERDICT: NOT PRIMARY - this node cannot serve writes. It has lost quorum or never joined. Check peer connectivity, then use 'Bootstrap / recover cluster from this node' on the node with the most recent data.");
            else
                lines.Add("VERDICT: PROBLEM - wsrep_ready=" + ready + ", wsrep_connected=" + connected + ". See the server log.");
            lines.Add(string.Empty);
        }
    }
}

// ---- what TCAdmin knows about the cluster ---------------------------------
var candidates = await DockerServiceManager.GetDbSet()
    .Include(x => x.ServerIp)
    .Include(x => x.Server)
    .Where(x => x.BlueprintId == service.BlueprintId && x.OwnerId == service.OwnerId)
    .ToListAsync(ThisCancellationToken);

var members = candidates
    .Where(x => string.Equals(ReadText(x.Variables, "clusterName", string.Empty), clusterName, StringComparison.OrdinalIgnoreCase))
    .OrderBy(x => x.ServiceId)
    .ToList();

lines.Add("Nodes TCAdmin knows about in cluster '" + clusterName + "': " + members.Count);
foreach (var member in members)
{
    var marker = member.ServiceId == service.ServiceId ? " >" : "  ";
    var role = string.Equals(ReadText(member.Variables, "nodeRole", "first"), "join", StringComparison.OrdinalIgnoreCase) ? "additional" : "first";
    lines.Add(marker + " #" + member.ServiceId + "  " + Pad(member.Name, 22) + Pad(member.IPAddress + ":" + member.Ports["Galera"], 24) + Pad(member.Status.ToString(), 10) + role);
}
if (members.Count > 0) lines.Add(string.Empty);
lines.Add("A healthy cluster has an ODD number of nodes (3, 5, ...) so a network split still leaves a majority.");

foreach (var line in lines) ScriptConsole.WriteLine("{0}", line);

static string ReadText(TCAdminVars source, string key, string fallback)
{
    if (source == null || !source.ContainsKey(key) || source[key] == null) return fallback;
    var text = source[key].ToString();
    if (text == null) return fallback;
    text = text.Trim();
    return text.Length == 0 ? fallback : text;
}

static string Pick(Dictionary<string, string> source, string key)
{
    string value;
    return source.TryGetValue(key, out value) ? value : "(not reported)";
}

static string Pad(string value, int width)
{
    value = value ?? string.Empty;
    if (value.Length >= width) return value + " ";
    return value + new string(' ', width - value.Length);
}

//refAssemblies: TCAdmin.SDK.dll, TCAdmin.Docker.SDK.dll, TCAdmin.Scripting.dll, TCAdmin.Monitor.dll, TCAdmin.Web.Shared.dll
using System;
using System.Collections.Generic;
using System.Linq;
using Microsoft.EntityFrameworkCore;
using TCAdmin.Web.Shared.Models;
using TCAdmin.Web.Shared.Models.Enums;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpDockerGlobals();

// Everything a user needs to (a) connect an application to this node and (b) add another
// node to the cluster. Works whether or not the container is running.

var service = await DockerServiceManager.GetAsync(ThisService.ServiceId);
if (service == null) { ScriptConsole.WriteLine("{0}", "FAILED: Service not found."); return; }

var clusterName = ReadText(service.Variables, "clusterName", "galera_cluster");
var nodeRole = string.Equals(ReadText(service.Variables, "nodeRole", "first"), "join", StringComparison.OrdinalIgnoreCase) ? "additional node" : "first node";
var password = ReadText(service.Variables, "RootPassword", string.Empty);
var ip = ThisService.IPAddress;
if (string.IsNullOrWhiteSpace(ip)) ip = service.IPAddress;

var lines = new List<string>();
lines.Add("Connection details");
lines.Add("  host     : " + ip);
lines.Add("  port     : " + service.Ports["Port"]);
lines.Add("  user     : root");
lines.Add("  password : " + (password.Length == 0 ? "(not generated yet - start the service once)" : password));
lines.Add("  cli      : mariadb -h " + ip + " -P " + service.Ports["Port"] + " -u root -p");
lines.Add(string.Empty);
lines.Add("Cluster");
lines.Add("  cluster name : " + clusterName);
lines.Add("  this node    : " + nodeRole);
lines.Add("  galera addr  : " + ip + ":" + service.Ports["Galera"]);
lines.Add("  ist / sst    : " + ip + ":" + service.Ports["IST"] + " / " + ip + ":" + service.Ports["SST"]);
lines.Add(string.Empty);

var candidates = await DockerServiceManager.GetDbSet()
    .Include(x => x.ServerIp)
    .Where(x => x.BlueprintId == service.BlueprintId && x.OwnerId == service.OwnerId)
    .ToListAsync(ThisCancellationToken);

var members = candidates
    .Where(x => string.Equals(ReadText(x.Variables, "clusterName", string.Empty), clusterName, StringComparison.OrdinalIgnoreCase))
    .OrderBy(x => x.ServiceId)
    .ToList();

lines.Add("Members of '" + clusterName + "' known to TCAdmin: " + members.Count);
foreach (var member in members)
{
    var marker = member.ServiceId == service.ServiceId ? " >" : "  ";
    lines.Add(marker + " #" + member.ServiceId + "  " + member.Name + "  " + member.IPAddress + ":" + member.Ports["Galera"] + "  (" + member.Status + ")");
}
lines.Add(string.Empty);
lines.Add("To add another node:");
lines.Add("  1. Create a new service on the 'MariaDB Galera Cluster' blueprint.");
lines.Add("  2. In the configuration step choose 'Additional node - join an existing cluster'.");
lines.Add("  3. Set the cluster name to exactly: " + clusterName);
lines.Add("  4. Leave the other fields blank - the node finds this cluster and inherits its root password.");
lines.Add(string.Empty);
lines.Add("Only fill in 'Existing node address(es)' and 'Cluster root password' when joining a cluster");
lines.Add("that this panel does not manage. For this cluster, that address list would be:");
lines.Add("  " + string.Join(",", members.Where(x => !string.IsNullOrWhiteSpace(x.IPAddress) && x.Ports["Galera"] != 0)
                                          .Select(x => x.IPAddress + ":" + x.Ports["Galera"])));

foreach (var line in lines) ScriptConsole.WriteLine("{0}", line);

static string ReadText(TCAdminVars source, string key, string fallback)
{
    if (source == null || !source.ContainsKey(key) || source[key] == null) return fallback;
    var text = source[key].ToString();
    if (text == null) return fallback;
    text = text.Trim();
    return text.Length == 0 ? fallback : text;
}

//refAssemblies: TCAdmin.SDK.dll, TCAdmin.Docker.SDK.dll, TCAdmin.Scripting.dll, TCAdmin.Monitor.dll, TCAdmin.Web.Shared.dll
using System;
using System.IO;
using System.Linq;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpDockerGlobals();

// Dumps the galera.cnf that was generated the last time this node started, plus the
// user-owned overrides. The SST credential line is masked - use 'Show connection details'
// when you actually need the password.

var service = await DockerServiceManager.GetAsync(ThisService.ServiceId);
if (service == null) { ScriptConsole.WriteLine("{0}", "FAILED: Service not found."); return; }

var galeraPath = Path.Combine(service.RootDirectory, "conf.d", "galera.cnf");
var customPath = Path.Combine(service.RootDirectory, "conf.d", "custom.cnf");

if (!File.Exists(galeraPath))
{
    ScriptConsole.WriteLine("{0}", "No generated configuration yet: " + galeraPath);
    ScriptConsole.WriteLine("{0}", "It is written every time the service starts. Start the service once, then run this again.");
}
else
{
    ScriptConsole.WriteLine("{0}", "conf.d/galera.cnf  (generated - mounted read-only at /etc/mysql/conf.d/galera.cnf)");
    ScriptConsole.WriteLine("{0}", "-----------------------------------------------------------------------------");
    foreach (var line in File.ReadAllLines(galeraPath))
    {
        var shown = line.TrimStart().StartsWith("wsrep_sst_auth", StringComparison.OrdinalIgnoreCase)
            ? "wsrep_sst_auth=root:********"
            : line;
        ScriptConsole.WriteLine("{0}", shown);
    }
    ScriptConsole.WriteLine("{0}", string.Empty);
}

if (File.Exists(customPath))
{
    ScriptConsole.WriteLine("{0}", "conf.d/custom.cnf  (yours - mounted at /etc/mysql/conf.d/zz-custom.cnf, read AFTER galera.cnf)");
    ScriptConsole.WriteLine("{0}", "-----------------------------------------------------------------------------");
    foreach (var line in File.ReadAllLines(customPath)) ScriptConsole.WriteLine("{0}", line);
    ScriptConsole.WriteLine("{0}", string.Empty);
}

ScriptConsole.WriteLine("{0}", "galera.cnf is rebuilt from config.json on every start - editing it directly has no effect.");
ScriptConsole.WriteLine("{0}", "Change settings in the service's Config Files -> config.json, or add raw options to conf.d/custom.cnf.");

//refAssemblies: TCAdmin.SDK.dll, TCAdmin.Docker.SDK.dll, TCAdmin.Scripting.dll, TCAdmin.Monitor.dll, TCAdmin.Web.Shared.dll, Docker.DotNet.dll
using System;
using System.Collections.Generic;
using System.Linq;
using Docker.DotNet;
using Docker.DotNet.Models;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpDockerGlobals();

// MariaDB logs to stderr, so the container log IS the error log. The live console only shows
// output since you opened it - this reads the last 400 lines back, which is what you need
// after a node has failed to start, and highlights the replication lines.

var service = await DockerServiceManager.GetAsync(ThisService.ServiceId);
if (service == null) { ScriptConsole.WriteLine("{0}", "FAILED: Service not found."); return; }

var containerName = "tca_svc_" + service.ServiceId;
var text = string.Empty;
try
{
    // Docker.DotNet 4.x: the old DockerClientConfiguration is gone; the parameterless builder
    // resolves the local unix socket / named pipe.
    using var client = new DockerClientBuilder().Build();
    var logStream = await client.Containers.GetContainerLogsAsync(containerName, new ContainerLogsParameters
    {
        ShowStdout = true,
        ShowStderr = true,
        Follow = false,
        Timestamps = false,
        Tail = "400"
    }, ThisCancellationToken);
    var (standardOutput, standardError) = await logStream.ReadOutputToEndAsync(ThisCancellationToken);
    text = (standardOutput ?? string.Empty) + (standardError ?? string.Empty);
}
catch (Exception ex)
{
    ScriptConsole.WriteLine("{0}", "FAILED: could not read the container log for " + containerName + ".");
    ScriptConsole.WriteLine("{0}", ex.Message);
    ScriptConsole.WriteLine("{0}", "If the service has never been started there is no container yet.");
    return;
}

var lines = text.Replace("\r\n", "\n").Replace('\r', '\n').Split('\n').Where(x => x.Trim().Length > 0).ToList();
if (lines.Count == 0)
{
    ScriptConsole.WriteLine("{0}", "The container log is empty.");
    return;
}

var interesting = new[] { "wsrep", "galera", "sst", "ist ", "[error]", "[warning]", "[fatal]", "gcomm", "quorum", "state transfer" };
var highlights = lines.Where(x => interesting.Any(k => x.IndexOf(k, StringComparison.OrdinalIgnoreCase) >= 0)).ToList();

ScriptConsole.WriteLine("{0}", "Replication / error lines (" + highlights.Count + " of the last " + lines.Count + "):");
ScriptConsole.WriteLine("{0}", "-----------------------------------------------------------------------------");
foreach (var line in highlights.Skip(Math.Max(0, highlights.Count - 120))) ScriptConsole.WriteLine("{0}", line.TrimEnd());

ScriptConsole.WriteLine("{0}", string.Empty);
ScriptConsole.WriteLine("{0}", "Full tail (last 40 lines):");
ScriptConsole.WriteLine("{0}", "-----------------------------------------------------------------------------");
foreach (var line in lines.Skip(Math.Max(0, lines.Count - 40))) ScriptConsole.WriteLine("{0}", line.TrimEnd());

ScriptConsole.WriteLine("{0}", string.Empty);
ScriptConsole.WriteLine("{0}", "Common messages:");
ScriptConsole.WriteLine("{0}", "  'It may not be safe to bootstrap'  -> whole cluster is down; use 'Bootstrap / recover cluster' on the node with the highest seqno.");
ScriptConsole.WriteLine("{0}", "  'failed to reach primary view'     -> this node cannot reach the others; run 'Test peer connectivity'.");
ScriptConsole.WriteLine("{0}", "  'Process completed with error: wsrep_sst_mariabackup' -> state transfer failed; check the donor's log too.");

//refAssemblies: TCAdmin.SDK.dll, TCAdmin.Docker.SDK.dll, TCAdmin.Scripting.dll, TCAdmin.Monitor.dll, TCAdmin.Web.Shared.dll
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using Microsoft.EntityFrameworkCore;
using TCAdmin.SDK.DynamicInput.Controls;
using TCAdmin.Web.Shared.Models;
using TCAdmin.Web.Shared.Models.DynamicInput;
using TCAdmin.Web.Shared.Models.Enums;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpDockerGlobals();

// Galera replicates the user change to every node by itself. What it does NOT do is update
// what TCAdmin has stored for the other node services, or the wsrep_sst_auth line baked into
// each node's generated galera.cnf - so this also rewrites the stored password on every
// member and tells you to roll a restart.

if (ThisService.Status != EServiceStatus.Started) { ScriptConsole.WriteLine("{0}", "This node is not running. Start it and try again."); return; }
if (!IsInteractive) { ScriptConsole.WriteLine("{0}", "Run this action from the panel."); return; }

var service = await DockerServiceManager.GetAsync(ThisService.ServiceId);
if (service == null) { ScriptConsole.WriteLine("{0}", "FAILED: Service not found."); return; }

var currentPassword = ReadText(service.Variables, "RootPassword", string.Empty);
if (currentPassword.Length == 0) { ScriptConsole.WriteLine("{0}", "FAILED: no root password is stored for this node."); return; }

var box = new DynamicTextBox
{
    Id = "NewPassword",
    Label = "New root password",
    Description = "Applied to every node in the cluster.",
    Required = true,
    InputType = 1
};
var answer = await ThisScript.Input(new InputConfiguration { IsDialog = true, AllowCancel = true }, box);
if (answer.Canceled) return;
var newPassword = answer.Values == null ? null : (answer.Values["NewPassword"] == null ? null : answer.Values["NewPassword"].ToString());
if (string.IsNullOrWhiteSpace(newPassword)) { ScriptConsole.WriteLine("{0}", "FAILED: New password is empty."); return; }
if (newPassword.IndexOf('\'') >= 0 || newPassword.IndexOf('\\') >= 0 || newPassword.IndexOf('\n') >= 0)
{
    ScriptConsole.WriteLine("{0}", "FAILED: the password cannot contain a single quote, a backslash or a newline.");
    return;
}

var root = service.RootDirectory;
var cnfPath = Path.Combine(root, ".tcadmin-mariadb.cnf");
var sqlPath = Path.Combine(root, ".tcadmin-password.sql");
var shPath = Path.Combine(root, ".tcadmin-password.sh");

File.WriteAllText(cnfPath, "[client]\nuser=root\npassword=" + currentPassword + "\n");
File.WriteAllText(sqlPath,
    "SET SESSION wsrep_on = ON;\n" +
    "ALTER USER 'root'@'localhost' IDENTIFIED BY '" + newPassword + "';\n" +
    "ALTER USER IF EXISTS 'root'@'%' IDENTIFIED BY '" + newPassword + "';\n" +
    "FLUSH PRIVILEGES;\n" +
    "SELECT 'TCA_PASSWORD_CHANGE_OK';\n");
File.WriteAllText(shPath,
    "#!/bin/sh\numask 077\np=/tmp/.tcadmin-mariadb.cnf\ntrap 'rm -f \"$p\"' EXIT\n" +
    "cp /mnt/server/.tcadmin-mariadb.cnf \"$p\"\n" +
    "if mariadb --defaults-extra-file=\"$p\" < /mnt/server/.tcadmin-password.sql; then echo 'SUCCESS: MariaDB root password changed.'; " +
    "else c=$?; echo \"FAILED: Password change failed (mariadb exit code $c).\"; exit $c; fi\n");

var output = string.Empty;
try
{
    var bytes = await DockerServiceManager.ExecConsoleSingleCommand(service, "/bin/sh /mnt/server/.tcadmin-password.sh", ThisCancellationToken);
    output = Encoding.UTF8.GetString(bytes);
}
finally
{
    try { File.Delete(cnfPath); File.Delete(sqlPath); File.Delete(shPath); } catch { }
}

foreach (var line in output.Replace("\r\n", "\n").Replace('\r', '\n').Split('\n'))
{
    if (line.Trim().Length > 0) ScriptConsole.WriteLine("{0}", line.TrimEnd());
}

if (output.IndexOf("SUCCESS: MariaDB root password changed.", StringComparison.Ordinal) < 0)
{
    ScriptConsole.WriteLine("{0}", "Nothing was changed in TCAdmin because the database change did not report success.");
    return;
}

// Update the stored password on this node and on every other member of the same cluster.
var clusterName = ReadText(service.Variables, "clusterName", "galera_cluster");
var candidates = await DockerServiceManager.GetDbSet()
    .Where(x => x.BlueprintId == service.BlueprintId && x.OwnerId == service.OwnerId)
    .ToListAsync(ThisCancellationToken);
var members = candidates
    .Where(x => x.ServiceId == service.ServiceId
             || string.Equals(ReadText(x.Variables, "clusterName", string.Empty), clusterName, StringComparison.OrdinalIgnoreCase))
    .ToList();

var updatedCount = 0;
foreach (var member in members)
{
    var updated = new TCAdminVars();
    if (member.Variables != null) foreach (var pair in member.Variables) updated[pair.Key] = pair.Value;
    if (string.Equals(ReadText(updated, "RootPassword", string.Empty), newPassword, StringComparison.Ordinal)) continue;
    updated["RootPassword"] = newPassword;
    // A joining node's override would otherwise re-apply the old password on its next start.
    if (ReadText(updated, "clusterRootPassword", string.Empty).Length > 0) updated["clusterRootPassword"] = newPassword;
    member.Variables = updated;
    DockerServiceManager.TCAdminDbContext.Entry(member).State = EntityState.Modified;
    updatedCount++;
}
if (updatedCount > 0) await DockerServiceManager.SaveChangesAsync(ThisCancellationToken);

ScriptConsole.WriteLine("{0}", "SUCCESS: new root password saved for " + updatedCount + " node(s) of cluster '" + clusterName + "'.");
ScriptConsole.WriteLine("{0}", string.Empty);
ScriptConsole.WriteLine("{0}", "IMPORTANT: each node still has the OLD password in its generated galera.cnf (wsrep_sst_auth),");
ScriptConsole.WriteLine("{0}", "which is what a state transfer authenticates with. Restart the nodes ONE AT A TIME, waiting");
ScriptConsole.WriteLine("{0}", "for each to report Synced in 'Galera cluster status' before restarting the next.");

static string ReadText(TCAdminVars source, string key, string fallback)
{
    if (source == null || !source.ContainsKey(key) || source[key] == null) return fallback;
    var text = source[key].ToString();
    if (text == null) return fallback;
    text = text.Trim();
    return text.Length == 0 ? fallback : text;
}

//refAssemblies: TCAdmin.SDK.dll, TCAdmin.Docker.SDK.dll, TCAdmin.Scripting.dll, TCAdmin.Monitor.dll
using System;
using System.IO;
using System.Text;
using System.Text.RegularExpressions;
using TCAdmin.Web.Shared.Models.Enums;
using TCAdmin.SDK.DynamicInput.Controls;
using TCAdmin.Web.Shared.Models.DynamicInput;
var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpDockerGlobals();
if(ThisService.Status!=EServiceStatus.Started){ScriptConsole.WriteLine("MariaDB is not running. Start the service and try again.");return;}if(!IsInteractive){ScriptConsole.WriteLine("Run this action from the panel.");return;}
var n=new DynamicTextBox { Id="Name", Label="Database name", Required=true }; var r=await ThisScript.Input(new InputConfiguration { IsDialog=true, AllowCancel=true },n); if(r.Canceled)return;
var v=r.Values?["Name"]?.ToString(); if(String.IsNullOrWhiteSpace(v))return;
if(!Regex.IsMatch(v,"^[A-Za-z0-9_]+$")){ScriptConsole.WriteLine("FAILED: Use only letters, numbers, and underscores in the database name.");return;}
var service=await DockerServiceManager.GetAsync(ThisService.ServiceId); if(service==null){ScriptConsole.WriteLine("FAILED: Service not found.");return;}
var p=service.Variables.Parse("RootPassword",string.Empty); if(String.IsNullOrWhiteSpace(p)){ScriptConsole.WriteLine("FAILED: Stored MariaDB root password is empty.");return;}
var root=service.RootDirectory;
var cnf=Path.Combine(root,".tcadmin-mariadb.cnf"); var sql=Path.Combine(root,".tcadmin-create-db.sql"); var sh=Path.Combine(root,".tcadmin-create-db.sh");
File.WriteAllText(cnf,"[client]\nuser=root\npassword="+p+"\n");
File.WriteAllText(sql,"CREATE DATABASE `"+v+"`;\n");
File.WriteAllText(sh,"#!/bin/sh\numask 077\nprivate=/tmp/.tcadmin-mariadb.cnf\ntrap 'rm -f \"$private\"' EXIT\ncp /mnt/server/.tcadmin-mariadb.cnf \"$private\"\nif mariadb --defaults-extra-file=\"$private\" < /mnt/server/.tcadmin-create-db.sql; then\n  echo \"SUCCESS: Database '"+v+"' was created.\"\nelse\n  code=$?\n  echo \"FAILED: Could not create database '"+v+"' (mariadb exit code $code).\"\n  exit $code\nfi\n");
var c="/bin/sh /mnt/server/.tcadmin-create-db.sh";
