//refAssemblies: TCAdmin.SDK.dll, TCAdmin.Docker.SDK.dll, TCAdmin.Scripting.dll, TCAdmin.Monitor.dll, TCAdmin.Web.Shared.dll, Docker.DotNet.dll
using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using Docker.DotNet.Models;
using Microsoft.EntityFrameworkCore;
using TCAdmin.SDK.Database.Entities;
using TCAdmin.Web.Shared.Models;
using TCAdmin.Web.Shared.Models.Enums;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpDockerGlobals(); // DO NOT MODIFY THIS LINE

// Builds /etc/mysql/conf.d/galera.cnf from config.json and hands the container a matching
// network layout. Runs on the hosting node's monitor immediately before the container is
// created, so every Start re-reads config.json and regenerates the file.
//
// The port rewrite below is the load-bearing part. TCAdmin publishes
// containerPort(fixed) -> hostPort(allocated), and the allocator bumps the whole port block
// when several nodes share an IP (4567 -> 4577 -> 4587). Galera advertises its own address to
// the rest of the cluster, so the number the container listens on must equal the number the
// host publishes. We therefore republish every port as hostPort->hostPort and write the same
// numbers into galera.cnf.

var startParams = ThisContainerStartParameters;
if (startParams == null) throw new InvalidOperationException("Galera: container start parameters are not available.");

// ConfigureContainer historically ran without DockerServiceManager in scope - only the task-step
// handler and the interactive script hub seeded it - so a script that used it died with a bare
// NullReferenceException surfacing as "Start failed". ServiceManager is always seeded
// (ScriptingEnvironmentFactory.AddCommonVariables), and its DbContext reaches DockerService just
// as well. Prefer the docker manager when a newer monitor provides it.
var dbContext = DockerServiceManager != null
    ? DockerServiceManager.TCAdminDbContext
    : (ServiceManager != null ? ServiceManager.TCAdminDbContext : null);
if (dbContext == null) throw new InvalidOperationException("Galera: no database context is available to this script.");

var service = await dbContext.Set<DockerService>()
    .Include(x => x.ServerIp)
    .FirstOrDefaultAsync(x => x.ServiceId == ThisService.ServiceId, ThisCancellationToken);
if (service == null) throw new InvalidOperationException("Galera: docker service not found.");

var settings = service.Variables ?? new TCAdminVars();

var nodeRole = ReadText(settings, "nodeRole", "first").ToLowerInvariant();
if (nodeRole != "join") nodeRole = "first";
var clusterName = ReadText(settings, "clusterName", "galera_cluster");
if (clusterName.Length == 0) clusterName = "galera_cluster";
var clusterAddressOverride = ReadText(settings, "clusterAddress", string.Empty);
var clusterRootPasswordOverride = ReadText(settings, "clusterRootPassword", string.Empty);
var maxConnections = ReadInt(settings, "maxConnections", 151, 10, 100000);
var bufferPoolMb = ReadInt(settings, "innodbBufferPoolSizeMB", 256, 64, 262144);
var gcacheMb = ReadInt(settings, "gcacheSizeMB", 128, 32, 65536);
var slaveThreads = ReadInt(settings, "wsrepSlaveThreads", 4, 1, 64);

var ipAddress = ThisService.IPAddress;
if (string.IsNullOrWhiteSpace(ipAddress)) ipAddress = service.IPAddress;
if (string.IsNullOrWhiteSpace(ipAddress)) throw new InvalidOperationException("Galera: this service has no allocated IP address.");

var mysqlPort = service.Ports["Port"];
var galeraPort = service.Ports["Galera"];
var istPort = service.Ports["IST"];
var sstPort = service.Ports["SST"];
if (mysqlPort == 0 || galeraPort == 0 || istPort == 0 || sstPort == 0)
    throw new InvalidOperationException("Galera: this service is missing one of the Port/Galera/IST/SST port allocations. Recreate the service on a blueprint that defines all four.");

// ---------------------------------------------------------------------------
// Cluster members: same blueprint, same owner, same cluster name. Variables is a JSON
// column so the cluster-name match has to happen after materialisation.
// ---------------------------------------------------------------------------
var candidates = await dbContext.Set<DockerService>()
    .Include(x => x.ServerIp)
    .Where(x => x.BlueprintId == service.BlueprintId
                && x.ServiceId != service.ServiceId
                && x.OwnerId == service.OwnerId)
    .ToListAsync(ThisCancellationToken);

var members = candidates
    .Where(x => string.Equals(ReadText(x.Variables, "clusterName", string.Empty), clusterName, StringComparison.OrdinalIgnoreCase))
    .OrderBy(x => x.ServiceId)
    .ToList();
var runningMembers = members.Where(x => x.Status == EServiceStatus.Started).ToList();

// ---------------------------------------------------------------------------
// Root password. Stored under RootPassword (never a config.json key - a blank field there
// would reverse-sync over it and wipe it). A joining node inherits the cluster's password,
// because SST overwrites the mysql schema with the donor's anyway.
// ---------------------------------------------------------------------------
var storedPassword = ReadText(settings, "RootPassword", string.Empty);
var password = storedPassword;

if (nodeRole == "join" && clusterRootPasswordOverride.Length > 0)
{
    password = clusterRootPasswordOverride;
}
else if (password.Length == 0 && nodeRole == "join")
{
    foreach (var member in members)
    {
        var candidate = ReadText(member.Variables, "RootPassword", string.Empty);
        if (candidate.Length > 0) { password = candidate; break; }
    }
    if (password.Length == 0)
        throw new InvalidOperationException("Galera: this node is set to join cluster '" + clusterName +
            "' but no existing node of that cluster was found to inherit the root password from. Create the first node of the cluster first, or fill in 'Cluster root password' in config.json.");
}
else if (password.Length == 0)
{
    var entropy = new byte[24];
    RandomNumberGenerator.Fill(entropy);
    password = Convert.ToBase64String(entropy).Replace("+", "-").Replace("/", "_").TrimEnd('=');
}

// ---------------------------------------------------------------------------
// Bootstrap decision. "First node" only bootstraps when no other member of the cluster is
// running - otherwise a node-1 restart would split the cluster in two. ForceBootstrap is the
// one-shot flag set by the "Bootstrap / recover cluster" action.
// ---------------------------------------------------------------------------
var forceBootstrap = string.Equals(ReadText(settings, "ForceBootstrap", string.Empty), "true", StringComparison.OrdinalIgnoreCase);
var bootstrap = forceBootstrap || (nodeRole == "first" && runningMembers.Count == 0);

var updatedVars = new TCAdminVars();
foreach (var pair in settings) updatedVars[pair.Key] = pair.Value;
var dirty = false;
if (!string.Equals(storedPassword, password, StringComparison.Ordinal)) { updatedVars["RootPassword"] = password; dirty = true; }
if (forceBootstrap) { updatedVars["ForceBootstrap"] = "false"; dirty = true; }
if (dirty)
{
    // Variables is a JSON column with no ValueComparer - DetectChanges misses both in-place
    // mutation and reassignment, so the entry has to be marked dirty explicitly.
    service.Variables = updatedVars;
    dbContext.Entry(service).State = EntityState.Modified;
    await dbContext.SaveChangesAsync(ThisCancellationToken);
}

// ---------------------------------------------------------------------------
// Peer list for gcomm://
// ---------------------------------------------------------------------------
var peerAddresses = new List<string>();
if (clusterAddressOverride.Length > 0)
{
    foreach (var part in clusterAddressOverride.Split(new[] { ',', ';', ' ', '\t' }, StringSplitOptions.RemoveEmptyEntries))
    {
        var entry = part.Trim();
        if (entry.Length == 0) continue;
        if (entry.IndexOf(':') < 0) entry = entry + ":4567";
        if (!peerAddresses.Contains(entry)) peerAddresses.Add(entry);
    }
}
else
{
    foreach (var member in members)
    {
        var memberIp = member.IPAddress;
        var memberPort = member.Ports["Galera"];
        if (string.IsNullOrWhiteSpace(memberIp) || memberPort == 0) continue;
        var entry = memberIp + ":" + memberPort.ToString(CultureInfo.InvariantCulture);
        if (!peerAddresses.Contains(entry)) peerAddresses.Add(entry);
    }
}

if (!bootstrap && peerAddresses.Count == 0)
    throw new InvalidOperationException("Galera: no cluster member to join. " +
        (nodeRole == "join"
            ? "Create the first node of cluster '" + clusterName + "' first, or fill in 'Existing node address(es)' in config.json."
            : "Another node of cluster '" + clusterName + "' appears to be running but its address could not be resolved."));

var gcomm = bootstrap ? "gcomm://" : "gcomm://" + string.Join(",", peerAddresses);

// ---------------------------------------------------------------------------
// galera.cnf
// ---------------------------------------------------------------------------
var nodeName = "node" + service.ServiceId.ToString(CultureInfo.InvariantCulture);
var nameSuffix = new string((service.Name ?? string.Empty).Where(c => char.IsLetterOrDigit(c) || c == '_' || c == '-').ToArray());
if (nameSuffix.Length > 0) nodeName = nodeName + "_" + (nameSuffix.Length > 24 ? nameSuffix.Substring(0, 24) : nameSuffix);

var root = service.RootDirectory;
var confDirectory = Path.Combine(root, "conf.d");
Directory.CreateDirectory(confDirectory);
var galeraCnfPath = Path.Combine(confDirectory, "galera.cnf");
var customCnfPath = Path.Combine(confDirectory, "custom.cnf");
if (!File.Exists(customCnfPath))
{
    File.WriteAllText(customCnfPath,
        "# Extra MariaDB options for this node.\n" +
        "#\n" +
        "# Mounted as /etc/mysql/conf.d/zz-custom.cnf, which MariaDB reads AFTER the generated\n" +
        "# galera.cnf - so anything set here wins. Restart the service to apply.\n" +
        "\n[mysqld]\n");
}

var cnf = new StringBuilder();
cnf.Append("# GENERATED BY TCADMIN - DO NOT EDIT.\n");
cnf.Append("# Rewritten from config.json every time this service starts.\n");
cnf.Append("# Put your own options in conf.d/custom.cnf instead; MariaDB reads it after this file.\n");
cnf.Append("\n[mysqld]\n");
cnf.Append("bind-address=0.0.0.0\n");
cnf.Append("port=" + mysqlPort.ToString(CultureInfo.InvariantCulture) + "\n");
cnf.Append("max_connections=" + maxConnections.ToString(CultureInfo.InvariantCulture) + "\n");
cnf.Append("innodb_buffer_pool_size=" + bufferPoolMb.ToString(CultureInfo.InvariantCulture) + "M\n");
cnf.Append("binlog_format=ROW\n");
cnf.Append("default_storage_engine=InnoDB\n");
cnf.Append("innodb_autoinc_lock_mode=2\n");
cnf.Append("innodb_flush_log_at_trx_commit=2\n");
cnf.Append("\n[galera]\n");
cnf.Append("wsrep_on=ON\n");
cnf.Append("wsrep_provider=/usr/lib/galera/libgalera_smm.so\n");
cnf.Append("wsrep_cluster_name=" + clusterName + "\n");
cnf.Append("wsrep_cluster_address=" + gcomm + "\n");
cnf.Append("wsrep_node_name=" + nodeName + "\n");
cnf.Append("wsrep_node_address=" + ipAddress + ":" + galeraPort.ToString(CultureInfo.InvariantCulture) + "\n");
cnf.Append("wsrep_node_incoming_address=" + ipAddress + ":" + mysqlPort.ToString(CultureInfo.InvariantCulture) + "\n");
cnf.Append("wsrep_slave_threads=" + slaveThreads.ToString(CultureInfo.InvariantCulture) + "\n");
cnf.Append("wsrep_sst_method=mariabackup\n");
cnf.Append("wsrep_sst_auth=root:" + password + "\n");
cnf.Append("wsrep_sst_receive_address=" + ipAddress + ":" + sstPort.ToString(CultureInfo.InvariantCulture) + "\n");
// Bind on every container interface, advertise the published host address. ist.recv_bind is
// what lets ist.recv_addr be an address the container itself cannot bind.
cnf.Append("wsrep_provider_options=\"base_port=" + galeraPort.ToString(CultureInfo.InvariantCulture) +
           "; gmcast.listen_addr=tcp://0.0.0.0:" + galeraPort.ToString(CultureInfo.InvariantCulture) +
           "; ist.recv_addr=" + ipAddress + ":" + istPort.ToString(CultureInfo.InvariantCulture) +
           "; ist.recv_bind=0.0.0.0" +
           "; gcache.size=" + gcacheMb.ToString(CultureInfo.InvariantCulture) + "M\"\n");
File.WriteAllText(galeraCnfPath, cnf.ToString());

// ---------------------------------------------------------------------------
// Container: publish hostPort -> hostPort so the advertised address is reachable.
// ---------------------------------------------------------------------------
startParams.HostConfig = startParams.HostConfig ?? new HostConfig();
startParams.ExposedPorts = new Dictionary<string, EmptyStruct>();
startParams.HostConfig.PortBindings = new Dictionary<string, IList<PortBinding>>();
foreach (var port in new[] { mysqlPort, galeraPort, istPort, sstPort })
{
    var key = port.ToString(CultureInfo.InvariantCulture) + "/tcp";
    startParams.ExposedPorts[key] = default(EmptyStruct);
    startParams.HostConfig.PortBindings[key] = new List<PortBinding>
    {
        new PortBinding { HostIP = ipAddress, HostPort = port.ToString(CultureInfo.InvariantCulture) }
    };
}

startParams.HostConfig.Mounts = startParams.HostConfig.Mounts ?? new List<Mount>();
startParams.HostConfig.Mounts.Add(new Mount { Type = "bind", Source = galeraCnfPath, Target = "/etc/mysql/conf.d/galera.cnf", ReadOnly = true });
startParams.HostConfig.Mounts.Add(new Mount { Type = "bind", Source = customCnfPath, Target = "/etc/mysql/conf.d/zz-custom.cnf", ReadOnly = true });

// The image's entrypoint runs as root and chowns/chmods the datadir it does not own; the
// default CapDrop list makes that fail. Network/ptrace hardening stays.
if (startParams.HostConfig.CapDrop != null)
{
    var restore = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "dac_override", "fowner", "fsetid" };
    startParams.HostConfig.CapDrop = startParams.HostConfig.CapDrop.Where(c => !restore.Contains(c)).ToList();
}

// mariabackup SST needs a real /tmp, not a 65 MB noexec one.
startParams.HostConfig.Tmpfs = new Dictionary<string, string> { { "/tmp", "rw,nosuid,size=1024m" } };

// Give the node time to leave the cluster cleanly and write a valid grastate.dat, otherwise
// every restart needs a full SST and a whole-cluster restart cannot find a safe bootstrap node.
startParams.StopTimeout = TimeSpan.FromSeconds(120);

startParams.Env = startParams.Env ?? new List<string>();
for (var i = startParams.Env.Count - 1; i >= 0; i--)
{
    var entry = startParams.Env[i] ?? string.Empty;
    if (entry.StartsWith("MARIADB_ROOT_PASSWORD=", StringComparison.Ordinal) ||
        entry.StartsWith("MARIADB_AUTO_UPGRADE=", StringComparison.Ordinal))
    {
        startParams.Env.RemoveAt(i);
    }
}
