static int ReadInt(TCAdminVars source, string key, int fallback, int minimum, int maximum)
{
    if (source == null || !source.ContainsKey(key) || source[key] == null) return fallback;
    double parsed;
    if (!double.TryParse(source[key].ToString(), NumberStyles.Any, CultureInfo.InvariantCulture, out parsed)) return fallback;
    var value = (int)Math.Round(parsed);
    if (value < minimum) return minimum;
    if (value > maximum) return maximum;
    return value;
}

//refAssemblies: TCAdmin.SDK.dll, TCAdmin.Docker.SDK.dll, TCAdmin.Scripting.dll, TCAdmin.Monitor.dll, TCAdmin.Web.Shared.dll
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Microsoft.EntityFrameworkCore;
using TCAdmin.Web.Shared.Models;
using TCAdmin.Web.Shared.Models.Enums;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpDockerGlobals();

// Recovery for the case where the whole cluster is down. Exactly ONE node must be told to
// start a new cluster from its own data; every other node then joins it. Galera refuses to
// bootstrap from a node it does not consider safe (safe_to_bootstrap: 0), which is what this
// action overrides - so it prints the node's recorded position first and makes you confirm.

if (!IsInteractive) { ScriptConsole.WriteLine("{0}", "Run this action from the panel."); return; }

var service = await DockerServiceManager.GetAsync(ThisService.ServiceId);
if (service == null) { ScriptConsole.WriteLine("{0}", "FAILED: Service not found."); return; }

if (ThisService.Status == EServiceStatus.Started)
{
    ScriptConsole.WriteLine("{0}", "This node is already running. Bootstrapping is only for restarting a cluster that is completely down.");
    ScriptConsole.WriteLine("{0}", "Stop the service first if you really need to force a new cluster from this node's data.");
    return;
}

var clusterName = ReadText(service.Variables, "clusterName", "galera_cluster");
var statePath = Path.Combine(service.RootDirectory, "database", "grastate.dat");

var uuid = "(unknown)";
var seqno = "(unknown)";
var safeToBootstrap = "(unknown)";
var stateLines = new List<string>();
if (File.Exists(statePath))
{
    stateLines = File.ReadAllLines(statePath).ToList();
    foreach (var line in stateLines)
    {
        var trimmed = line.Trim();
        if (trimmed.StartsWith("uuid:", StringComparison.OrdinalIgnoreCase)) uuid = trimmed.Substring(5).Trim();
        else if (trimmed.StartsWith("seqno:", StringComparison.OrdinalIgnoreCase)) seqno = trimmed.Substring(6).Trim();
        else if (trimmed.StartsWith("safe_to_bootstrap:", StringComparison.OrdinalIgnoreCase)) safeToBootstrap = trimmed.Substring(18).Trim();
    }
}

ScriptConsole.WriteLine("{0}", "Recorded state for this node (" + statePath + "):");
ScriptConsole.WriteLine("{0}", "  cluster uuid      : " + uuid);
ScriptConsole.WriteLine("{0}", "  seqno             : " + seqno + (seqno == "-1" ? "   (node was not shut down cleanly - its real position is only known after recovery)" : string.Empty));
ScriptConsole.WriteLine("{0}", "  safe_to_bootstrap : " + safeToBootstrap + (safeToBootstrap == "1" ? "   (Galera already considers this node safe)" : string.Empty));
ScriptConsole.WriteLine("{0}", string.Empty);

var candidates = await DockerServiceManager.GetDbSet()
    .Include(x => x.ServerIp)
    .Where(x => x.BlueprintId == service.BlueprintId && x.OwnerId == service.OwnerId)
    .ToListAsync(ThisCancellationToken);
var members = candidates
    .Where(x => string.Equals(ReadText(x.Variables, "clusterName", string.Empty), clusterName, StringComparison.OrdinalIgnoreCase))
    .Where(x => x.ServiceId != service.ServiceId)
    .ToList();
var running = members.Where(x => x.Status == EServiceStatus.Started).ToList();

if (running.Count > 0)
{
    ScriptConsole.WriteLine("{0}", "WARNING: " + running.Count + " other node(s) of '" + clusterName + "' are still running:");
    foreach (var member in running) ScriptConsole.WriteLine("{0}", "  #" + member.ServiceId + "  " + member.Name);
    ScriptConsole.WriteLine("{0}", "Bootstrapping now would create a SECOND, separate cluster and split your data.");
    ScriptConsole.WriteLine("{0}", "Just start this node normally instead - it will join the running cluster.");
    ScriptConsole.WriteLine("{0}", string.Empty);
}

var confirmed = await ThisScript.ShowMessageBox(
    "Bootstrap cluster from this node?",
    "This node will start a NEW cluster from the data it has on disk, and every other node will "
    + "have to re-sync from it. Any transactions that only exist on another node are lost.\n\n"
    + "Only do this when the whole cluster is down, and only on the node with the highest seqno.\n\n"
    + "Node: " + service.Name + " (#" + service.ServiceId + ")   cluster: " + clusterName
    + "\nseqno: " + seqno
    + (running.Count > 0 ? "\n\nWARNING: " + running.Count + " other node(s) are still running." : string.Empty),
    "Bootstrap from this node", "Cancel");

if (confirmed != true) { ScriptConsole.WriteLine("{0}", "Cancelled. Nothing changed."); return; }

// Galera reads safe_to_bootstrap from grastate.dat and refuses --wsrep-new-cluster when it is 0.
if (stateLines.Count > 0)
{
    var rewritten = new List<string>();
    var replaced = false;
    foreach (var line in stateLines)
    {
        if (line.TrimStart().StartsWith("safe_to_bootstrap:", StringComparison.OrdinalIgnoreCase))
        {
            rewritten.Add("safe_to_bootstrap: 1");
            replaced = true;
        }
        else rewritten.Add(line);
    }
    if (!replaced) rewritten.Add("safe_to_bootstrap: 1");
    File.WriteAllLines(statePath, rewritten);
    ScriptConsole.WriteLine("{0}", "safe_to_bootstrap set to 1 in grastate.dat.");
}
else
{
    ScriptConsole.WriteLine("{0}", "No grastate.dat found - this node has no recorded state yet, so nothing to override.");
}

var updated = new TCAdminVars();
if (service.Variables != null) foreach (var pair in service.Variables) updated[pair.Key] = pair.Value;
updated["ForceBootstrap"] = "true";
service.Variables = updated;
DockerServiceManager.TCAdminDbContext.Entry(service).State = EntityState.Modified;
await DockerServiceManager.SaveChangesAsync(ThisCancellationToken);

ScriptConsole.WriteLine("{0}", string.Empty);
ScriptConsole.WriteLine("{0}", "READY. Press Start on this service now - it will come up with --wsrep-new-cluster.");
ScriptConsole.WriteLine("{0}", "The flag is one-shot: the next start after that joins normally.");
ScriptConsole.WriteLine("{0}", "Once this node reports Synced, start the other nodes one at a time.");

