//refAssemblies: TCAdmin.SDK.dll, TCAdmin.Docker.SDK.dll, TCAdmin.Scripting.dll, TCAdmin.Monitor.dll, TCAdmin.Web.Shared.dll
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Microsoft.EntityFrameworkCore;
using TCAdmin.SDK.DynamicInput.Controls;
using TCAdmin.Web.Shared.Models;
using TCAdmin.Web.Shared.Models.DynamicInput;
using TCAdmin.Web.Shared.Models.Enums;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpDockerGlobals();

// Wipes this node's data directory so the next start pulls a complete copy from a healthy
// node (a full SST). This is the fix for a node whose local state is corrupt or too far
// behind to catch up. It is destructive and only safe while another node is running.

if (!IsInteractive) { ScriptConsole.WriteLine("{0}", "Run this action from the panel."); return; }

var service = await DockerServiceManager.GetAsync(ThisService.ServiceId);
if (service == null) { ScriptConsole.WriteLine("{0}", "FAILED: Service not found."); return; }

if (ThisService.Status != EServiceStatus.Stopped)
{
    ScriptConsole.WriteLine("{0}", "Stop this service first. Its data directory cannot be replaced while the container is running.");
    ScriptConsole.WriteLine("{0}", "Current status: " + ThisService.Status);
    return;
}

var clusterName = ReadText(service.Variables, "clusterName", "galera_cluster");

var candidates = await DockerServiceManager.GetDbSet()
    .Include(x => x.ServerIp)
    .Where(x => x.BlueprintId == service.BlueprintId && x.OwnerId == service.OwnerId)
    .ToListAsync(ThisCancellationToken);
var members = candidates
    .Where(x => string.Equals(ReadText(x.Variables, "clusterName", string.Empty), clusterName, StringComparison.OrdinalIgnoreCase))
    .Where(x => x.ServiceId != service.ServiceId)
    .ToList();
var running = members.Where(x => x.Status == EServiceStatus.Started).ToList();

if (running.Count == 0)
{
    ScriptConsole.WriteLine("{0}", "REFUSED: no other node of cluster '" + clusterName + "' is running.");
    ScriptConsole.WriteLine("{0}", "Wiping this node now would destroy the only copy of the data. Start a healthy node first,");
    ScriptConsole.WriteLine("{0}", "or use 'Bootstrap / recover cluster from this node' if this node holds the data you want to keep.");
    return;
}

var dataDirectory = Path.Combine(service.RootDirectory, "database");
long sizeBytes = 0;
if (Directory.Exists(dataDirectory))
{
    foreach (var file in Directory.EnumerateFiles(dataDirectory, "*", SearchOption.AllDirectories))
    {
        try { sizeBytes += new FileInfo(file).Length; } catch { }
    }
}

ScriptConsole.WriteLine("{0}", "Data directory : " + dataDirectory);
ScriptConsole.WriteLine("{0}", "Current size   : " + (sizeBytes / 1024 / 1024) + " MB");
ScriptConsole.WriteLine("{0}", "Donor(s) online: " + string.Join(", ", running.Select(x => "#" + x.ServiceId + " " + x.Name)));
ScriptConsole.WriteLine("{0}", string.Empty);

var confirmation = new DynamicTextBox
{
    Id = "Confirm",
    Label = "Type RESYNC to confirm",
    Description = "Everything in this node's data directory is deleted and re-fetched from a running node.",
    Required = true
};
var answer = await ThisScript.Input(new InputConfiguration { IsDialog = true, AllowCancel = true }, confirmation);
if (answer.Canceled) { ScriptConsole.WriteLine("{0}", "Cancelled. Nothing changed."); return; }
var typed = answer.Values == null ? null : (answer.Values["Confirm"] == null ? null : answer.Values["Confirm"].ToString());
if (!string.Equals((typed ?? string.Empty).Trim(), "RESYNC", StringComparison.Ordinal))
{
    ScriptConsole.WriteLine("{0}", "Cancelled: confirmation text did not match. Nothing changed.");
    return;
}

var removed = 0;
var failed = new List<string>();
if (Directory.Exists(dataDirectory))
{
    foreach (var directory in Directory.GetDirectories(dataDirectory))
    {
        try { Directory.Delete(directory, true); removed++; } catch (Exception ex) { failed.Add(directory + ": " + ex.Message); }
    }
    foreach (var file in Directory.GetFiles(dataDirectory))
    {
        try { File.Delete(file); removed++; } catch (Exception ex) { failed.Add(file + ": " + ex.Message); }
    }
}
else
{
    Directory.CreateDirectory(dataDirectory);
}

ScriptConsole.WriteLine("{0}", "Removed " + removed + " entries from the data directory.");
foreach (var failure in failed) ScriptConsole.WriteLine("{0}", "  COULD NOT DELETE " + failure);

if (failed.Count > 0)
{
    ScriptConsole.WriteLine("{0}", "FAILED: some files could not be removed. The node will not resync cleanly until they are gone.");
    return;
}

ScriptConsole.WriteLine("{0}", string.Empty);
ScriptConsole.WriteLine("{0}", "DONE. Press Start - the node will initialise and then pull a full copy from a running node.");
ScriptConsole.WriteLine("{0}", "A full state transfer can take a while on a large database; watch 'Galera cluster status'.");

