//refAssemblies: TCAdmin.SDK.dll, TCAdmin.Docker.SDK.dll, TCAdmin.Scripting.dll, TCAdmin.Monitor.dll, TCAdmin.Web.Shared.dll
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using Microsoft.EntityFrameworkCore;
using TCAdmin.Web.Shared.Models;
using TCAdmin.Web.Shared.Models.Enums;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpDockerGlobals();

// Probes every address this node needs to reach, FROM INSIDE the container - which is the
// only vantage point that matters. It also probes this node's own published ports, because
// a container reaching its own host-published port is the case that breaks first when the
// Docker daemon runs without the userland proxy.

var service = await DockerServiceManager.GetAsync(ThisService.ServiceId);
if (service == null) { ScriptConsole.WriteLine("{0}", "FAILED: Service not found."); return; }
if (ThisService.Status != EServiceStatus.Started)
{
    ScriptConsole.WriteLine("{0}", "This node must be running to probe from inside its container. Start it and try again.");
    return;
}

var clusterName = ReadText(service.Variables, "clusterName", "galera_cluster");
var ip = ThisService.IPAddress;
if (string.IsNullOrWhiteSpace(ip)) ip = service.IPAddress;

var candidates = await DockerServiceManager.GetDbSet()
    .Include(x => x.ServerIp)
    .Where(x => x.BlueprintId == service.BlueprintId && x.OwnerId == service.OwnerId)
    .ToListAsync(ThisCancellationToken);

var members = candidates
    .Where(x => string.Equals(ReadText(x.Variables, "clusterName", string.Empty), clusterName, StringComparison.OrdinalIgnoreCase))
    .OrderBy(x => x.ServiceId)
    .ToList();

var targets = new List<string>();
foreach (var member in members)
{
    var memberIp = member.IPAddress;
    if (string.IsNullOrWhiteSpace(memberIp)) continue;
    var label = (member.ServiceId == service.ServiceId ? "self #" : "node #") + member.ServiceId;
    targets.Add(label + " mysql|" + memberIp + "|" + member.Ports["Port"]);
    targets.Add(label + " galera|" + memberIp + "|" + member.Ports["Galera"]);
    targets.Add(label + " ist|" + memberIp + "|" + member.Ports["IST"]);
    targets.Add(label + " sst|" + memberIp + "|" + member.Ports["SST"]);
}

if (targets.Count == 0)
{
    ScriptConsole.WriteLine("{0}", "No cluster members with a resolvable address were found for cluster '" + clusterName + "'.");
    return;
}

var script = new StringBuilder();
script.Append("#!/bin/bash\n");
foreach (var target in targets)
{
    var parts = target.Split('|');
    if (parts.Length != 3) continue;
    if (parts[2] == "0") { script.Append("echo 'SKIP  " + parts[0] + " (no port allocated)'\n"); continue; }
    script.Append("if timeout 4 bash -c 'exec 3<>/dev/tcp/" + parts[1] + "/" + parts[2] + "' 2>/dev/null; then ");
    script.Append("echo 'OK    " + parts[0] + "  " + parts[1] + ":" + parts[2] + "'; else ");
    script.Append("echo 'FAIL  " + parts[0] + "  " + parts[1] + ":" + parts[2] + "'; fi\n");
}

var root = service.RootDirectory;
var shPath = Path.Combine(root, ".tcadmin-galera-probe.sh");
File.WriteAllText(shPath, script.ToString());

var output = string.Empty;
try
{
    var bytes = await DockerServiceManager.ExecConsoleSingleCommand(service, "/bin/bash /mnt/server/.tcadmin-galera-probe.sh", ThisCancellationToken);
    output = Encoding.UTF8.GetString(bytes);
}
finally
{
    try { File.Delete(shPath); } catch { }
}

var results = output.Replace("\r\n", "\n").Replace('\r', '\n').Split('\n').Where(x => x.Trim().Length > 0).ToList();
ScriptConsole.WriteLine("{0}", "Connectivity probed from inside this node's container:");
foreach (var line in results) ScriptConsole.WriteLine("{0}", "  " + line.Trim());

ScriptConsole.WriteLine("{0}", string.Empty);
ScriptConsole.WriteLine("{0}", "Note: these probes hit Docker's published ports, which accept a connection even when nothing");
ScriptConsole.WriteLine("{0}", "is listening behind them yet - IST and SST only bind during an actual state transfer. An OK");
ScriptConsole.WriteLine("{0}", "means the network path is open, not that a transfer is running.");

var failures = results.Count(x => x.TrimStart().StartsWith("FAIL", StringComparison.Ordinal));
var selfFailures = results.Count(x => x.Contains("self #", StringComparison.Ordinal) && x.TrimStart().StartsWith("FAIL", StringComparison.Ordinal));
ScriptConsole.WriteLine("{0}", string.Empty);
if (failures == 0)
{
    ScriptConsole.WriteLine("{0}", "VERDICT: every cluster address is reachable from this node.");
}
else
{
    ScriptConsole.WriteLine("{0}", "VERDICT: " + failures + " address(es) unreachable.");
    if (selfFailures > 0)
    {
        ScriptConsole.WriteLine("{0}", "  This node cannot reach its OWN published ports. Nodes on the same physical server");
        ScriptConsole.WriteLine("{0}", "  talk to each other through the host address, so that has to work. Check that the");
        ScriptConsole.WriteLine("{0}", "  Docker daemon on this server has the userland proxy enabled, or add a hairpin NAT");
        ScriptConsole.WriteLine("{0}", "  rule for the tcadmin0 subnet.");
    }
    ScriptConsole.WriteLine("{0}", "  A node that is Stopped will always fail - that is expected. For a node that is");
    ScriptConsole.WriteLine("{0}", "  running, check the firewall between the two servers: Galera needs 4567, 4568 and");
    ScriptConsole.WriteLine("{0}", "  4444 open in both directions, not just the MariaDB port.");
}

